import unicodedata


def _char_width(c: str) -> int:
    cat = unicodedata.category(c)
    if cat in ("Mn", "Me", "Cf"):
        return 0
    if unicodedata.east_asian_width(c) in ("W", "F"):
        return 2
    return 1


def fit(text: str, width: int) -> str:
    total = sum(_char_width(c) for c in text)
    if total <= width:
        return text

    budget = width - 1  # reserve one column for the ellipsis
    acc = 0             # column width of text[:i]
    cut = 0             # best cut index found so far
    for i, c in enumerate(text):
        wc = _char_width(c)
        if wc > 0:
            # Cutting before a nonzero-width char is a valid boundary.
            if acc <= budget:
                cut = i
            else:
                break
        acc += wc

    return text[:cut] + "…"
